# Écosystème : ajouter 354 logos validés par Claude
# Lots R049 à R060, originaux vérifiés et rapprochements des fiches publiques.
# Fonds adaptés ; 354 fiches contrôlées à 320 px ; sources conservées.
import base64,hashlib,json,pathlib,zlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
PAYLOAD=""""""
entries=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
for e in entries:
 p=(ROOT/e['path']).resolve()
 assert p.is_relative_to(ROOT),e['path']
 current=hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
 assert current in (e['before'],e['after']), 'Fichier modifié depuis préparation : '+e['path']
 raw=base64.b64decode(e['data']);assert hashlib.sha256(raw).hexdigest()==e['after']
for e in entries:
 p=ROOT/e['path'];p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(e['data']))
print('354 logos validés intégrés ; 713 fichiers vérifiés et appliqués.')
